/* ================= 词库数据（源自 K2 融合版 §7 / §8） ================= */
function norm(a){return a.map(function(x){
  if(typeof x==='string') return {v:x,t:x};
  return {v:x[0], t:x[1], risk:!!x[2], nsfw:!!x[3], water:!!x[4]};
});}

