function handPoolFor(pose){
  var tag = pose ? POSE_HAND[pose] : null;
  if(!tag || !HAND_POOLS[tag]) return OPT.poseExtra.slice(); /* 未选姿态或未标注：全池自由 */
  var pool=[{v:'不启用',t:''}];
  HAND_POOLS[tag].forEach(function(n){
    var o=OPT.poseExtra.filter(function(x){return x.v===n;})[0];
    if(o) pool.push({v:o.v,t:o.t});
  });
  return pool;
}
/* 情绪表情 → 眼神方向 串联：选情绪时眼神下拉只列适配方向，杜绝「害羞+直视镜头」类矛盾 */
