/* ===== 交合模拟动作库：模式池 / 场景环境映射 / 智能匹配 ===== */
OPT.simMode = norm(['不启用','手动选类','智能匹配']);
OPT.simCat = norm(['不启用','A仰面承重','B俯面承重','C侧身承重','D跪撑','E坐姿','F站立','G蹲姿','H悬空','I过渡动态','J混合特殊']);
