OPT.sfwSimCat = norm(['不启用','A仰面承重','B俯面承重','C侧身承重','D跪撑','E坐姿','F站立','G蹲姿','H悬空','I过渡动态','J混合特殊']);
OPT.sfwSimCoreCat = OPT.sfwSimCat;
