SCENE_ENV['__default'] = ['地','墙'];

function simModeActive(){ var m=v('simMode'); return m && m!=='' && m!=='不启用'; }
/* 核心姿态大类判定（禁用同类规则用）：仅读显式声明 simCoreCat，SFW pose 残留不再偷偷生效 */
function coreSimCat(){
  var sc=v('simCoreCat'); if(!sc || sc==='不启用') return null;
  return sc.charAt(0);
}
/* simPick 下拉：按大类填充（A001 仰躺，肩胛骨触地…） */
function populateSimPick(cat){
  var sel=$('simPick'); if(!sel) return;
  var arr=(SIM_POSES[cat]||[]).map(function(x){ return {v:x.id, t:x.t}; });
  fillSelect(sel, arr, true);
  if(!cat) sel.value='';
}
/* 手动选择的动作描述 */
function simPickText(){
  var p=v('simPick'); if(!p) return '';
  var item=(SIM_POSES[p.charAt(0)]||[]).filter(function(x){return x.id===p;})[0];
  return item?item.t:'';
}
/* 智能匹配：剔除核心同类 → 九类各抽 1 → 按环境关键词打分 → 取最高分（平局随机）；全 0 分时兜底含「地」候选 */
function smartSimPick(){
  var env=SCENE_ENV[v('scene')]||SCENE_ENV['__default'];
  var core=coreSimCat();
  var cats=['A','B','C','D','E','F','G','H','I','J'].filter(function(c){return c!==core;});
  var cands=cats.map(function(c){
    var arr=SIM_POSES[c]||[];
    return arr[Math.floor(Math.random()*arr.length)];
  }).filter(Boolean);
  cands.forEach(function(it){ it._score=env.filter(function(kw){return it.t.indexOf(kw)>=0;}).length; });
  cands.sort(function(a,b){return b._score-a._score;});
  if(cands[0]._score>0){
    var best=cands.filter(function(it){return it._score===cands[0]._score;});
    return best[Math.floor(Math.random()*best.length)].t;
  }
  /* 全 0 分兜底：优先取含「地」的候选（多数场景有地面支撑），避免与场景完全脱节 */
  var ground=cands.filter(function(it){return it.t.indexOf('地')>=0;});
  if(ground.length) return ground[Math.floor(Math.random()*ground.length)].t;
  return cands[Math.floor(Math.random()*cands.length)].t;
}
/* simMode 变化 → simCoreCat/simCat/simPick 显隐联动 */
function syncSimFields(){
  var m=v('simMode');
  var smart = (m==='智能匹配'), manual = (m==='手动选类');
  var wc=$('fw_simCoreCat'); if(wc) wc.style.display = smart?'':'none';
  ['simCat','simPick'].forEach(function(id){
    var w=$('fw_'+id); if(w) w.style.display=manual?'':'none';
  });
  if(manual) populateSimPick(v('simCat'));
}

/* ===== SFW 擦边动作库：populate/smart/sync（与 NSFW 动作库同构） ===== */
